DateTime d(int month, int day) => DateTime.utc(2026, month, day);

const _fakeModel = PdfExportModel(
  cycles: [],
  markOpenedIndexes: [0],
  overlays: [],
  observedCyclesOutsideApp: 3,
  name: 'Maria Muster',
  birthDate: null,
  shortestCycleLengths: [27],
  earliestFirstHigherCycleDays: [14],
);

/// Fixture data: two mark-opened cycles (Mar 1..28: 28 days; Mar 29..Apr 28:
/// 31 days), notes on some days with umlauts and non-Latin-1 glyphs.
List<DailyEntry> fixtureEntries() => [
  for (var i = 0; i < 28; i++)
    DailyEntry(
      date: d(3, 1 + i),
      bbtC: 36.0 + (i % 10) / 10,
      notes: i == 3
          ? 'Querdenken im Büro — schöner Tag ß'
          : (i == 10 ? 'Ж α ž' : null),
    ),
  for (var i = 0; i < 31; i++) DailyEntry(date: d(3, 29 + i), bbtC: 36.2),
];

List<CycleMark> fixtureMarks() => [
  CycleMark(date: d(3, 1), type: CycleMarkTypes.cycleStart),
  CycleMark(date: d(3, 29), type: CycleMarkTypes.cycleStart),
];

PdfExportModel fixtureModel() => buildPdfExportModel(
  entries: fixtureEntries(),
  marks: fixtureMarks(),
  observedCyclesOutsideApp: 3,
  name: 'Maria Muster',
  birthDate: d(12, 24),
  // The span extension runs the LAST cycle out to "today"; the fixture
  // pins the clock at the second cycle's last tracked day so the 2-cycle
  // plan below stays deterministic.
  today: d(4, 28),
);

/// The bundled asset font, read from the checkout (the smoke path mirrors
/// what the app loads via rootBundle; see lib/pdf/cycle_pdf.dart).
List<int> fixtureFontBytes() =>
    File('assets/fonts/NotoSans-Regular.ttf').readAsBytesSync();

/// Counts the uncompressed page markers: with `compress: false` every page
/// object dictionary appears verbatim as `/Type/Page/` (the `/Pages` node
/// does not match — its "Page" is followed by an "s", not a "/").
int countPageMarkers(List<int> bytes) {
  final pattern = '/Type/Page/'.codeUnits;
  var count = 0;
  for (var i = 0; i + pattern.length <= bytes.length; i++) {
    var hit = true;
    for (var j = 0; j < pattern.length; j++) {
      if (bytes[i + j] != pattern[j]) {
        hit = false;
        break;
      }
    }
    if (hit) count++;
  }
  return count;
}

String valueOf(List<({String label, String value})> facts, String label) =>
    facts.firstWhere((f) => f.label == label).value;

/// All fill-color operations (`r g b rg`) of one page content stream, as
/// channel tuples in emission order. Uncompressed generation emits the
/// colors verbatim; the pdf package's number formatting is absorbed by
/// the comparison tolerance below.
List<List<double>> fillColorTuples(String stream) => [
  for (final match in RegExp(
    r'([0-9.]+) ([0-9.]+) ([0-9.]+) rg',
  ).allMatches(stream))
    [
      double.parse(match.group(1)!),
      double.parse(match.group(2)!),
      double.parse(match.group(3)!),
    ],
];

/// The print-friendly weekend shade: near-white Light GRAY (all three
/// channels equal, luminance ~230) — never a pale color, and far from
/// every ink/accent darkness so nothing above it loses legibility.
const _weekendShade = 230 / 255;

/// The generated fixture document, uncompressed so the content streams
/// stay verbatim (byte-level checks).
Future<List<int>> generateFixture() => generatePdfBytes(
  model: fixtureModel(),
  fontBytes: fixtureFontBytes(),
  options: PdfExportOptions(anonymized: false),
  compress: false,
);

/// The [index]-th page's content stream bytes (0-based, print order): the
/// index-th `/Contents <n> 0 R` de-referenced, uncompressed stream
/// (compress: false).
String pageContentStream(List<int> bytes, int index) {
  final latin = latin1.decode(bytes);
  final refs = RegExp(r'/Contents (\d+) 0 R').allMatches(latin).toList();
  if (index >= refs.length) {
    fail('page $index has no /Contents reference (found ${refs.length})');
  }
  final n = refs[index].group(1)!;
  final obj = RegExp('$n 0 obj(.*?)endstream', dotAll: true).firstMatch(latin);
  if (obj == null) {
    fail('content object $n not found');
  }
  final start = obj.group(1)!.indexOf('stream\n');
  return obj.group(1)!.substring(start + 'stream\n'.length);
}

/// The first page's content stream bytes.
String firstPageContentStream(List<int> bytes) => pageContentStream(bytes, 0);

// Content-stream extraction: the document is generated UNCOMPRESSED
// (compress: false), so these operator reads are byte-exact.

/// One extracted text run: the decoded text, its baseline origin and the used
/// font size, in page coordinates (y-up).
final class PdfTextRun {
  const PdfTextRun(this.text, this.x, this.y, this.fontSize);

  final String text;
  final double x;
  final double y;
  final double fontSize;
}

/// One painted path of the page: its color (fill or stroke), whether it
/// is filled, and the bounding box of the path's points, in page
/// coordinates (y-up).
final class PdfInkPath {
  const PdfInkPath(
    this.color,
    this.minX,
    this.minY,
    this.maxX,
    this.maxY, {
    this.filled = true,
  });

  final List<double> color;
  final double minX;
  final double minY;
  final double maxX;
  final double maxY;

  final bool filled;
}

/// The document's ToUnicode CMap: glyph code → Unicode rune (the pdf package
/// writes one CMap per font as `beginbfchar <code> <unicode> endbfchar`).
Map<int, int> _codeToRuneMap(String document) {
  final map = <int, int>{};
  final block = RegExp('beginbfchar([\\s\\S]*?)endbfchar');
  final entry = RegExp('<([0-9A-F]{4})> <([0-9A-F]{4})>');
  for (final match in block.allMatches(document)) {
    for (final pair in entry.allMatches(match.group(1)!)) {
      map[int.parse(pair.group(1)!, radix: 16)] = int.parse(
        pair.group(2)!,
        radix: 16,
      );
    }
  }
  return map;
}

/// A 2D transform as the PDF operand order (a b c d e f); the returned matrix
/// applies [inner] first, then [outer].
List<double> _compose(List<double> outer, List<double> inner) => [
  outer[0] * inner[0] + outer[2] * inner[1],
  outer[1] * inner[0] + outer[3] * inner[1],
  outer[0] * inner[2] + outer[2] * inner[3],
  outer[1] * inner[2] + outer[3] * inner[3],
  outer[0] * inner[4] + outer[2] * inner[5] + outer[4],
  outer[1] * inner[4] + outer[3] * inner[5] + outer[5],
];

List<double> _apply(List<double> m, double x, double y) => [
  m[0] * x + m[2] * y + m[4],
  m[1] * x + m[3] * y + m[5],
];

PdfInkPath _pathOf(
  List<double> color,
  List<List<double>> points, {
  bool filled = true,
}) {
  var minX = points.first[0];
  var minY = points.first[1];
  var maxX = minX;
  var maxY = minY;
  for (final p in points.skip(1)) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  return PdfInkPath(color, minX, minY, maxX, maxY, filled: filled);
}

/// Extracts a page's (default: the first's) text runs and painted paths
/// (fills and ink strokes).
(List<PdfTextRun>, List<PdfInkPath>) extractPageContent(
  List<int> bytes, {
  int page = 0,
}) {
  final document = latin1.decode(bytes);
  final runes = _codeToRuneMap(document);
  final tokens = RegExp(
    '[^ ]+',
  ).allMatches(pageContentStream(bytes, page)).map((m) => m.group(0)!).toList();

  final runs = <PdfTextRun>[];
  final paths = <PdfInkPath>[];

  var ctm = <double>[1, 0, 0, 1, 0, 0];
  final saved = <List<double>>[];
  final pending = <double>[];
  final pathPoints = <List<double>>[];
  var fill = <double>[0, 0, 0];
  var stroke = <double>[0, 0, 0];
  double fontSize = 0;
  double textX = 0;
  double textY = 0;

  for (final token in tokens) {
    final value = double.tryParse(token);
    if (value != null) {
      pending.add(value);
      continue;
    }
    if (token.startsWith('[') && token.endsWith(']TJ')) {
      // The text-showing token carries the font's glyph codes as one hex
      // string: "[<0123…>]TJ" (Identity-H, 2-byte codes).
      final hex = RegExp('<([0-9A-Fa-f]*)>').firstMatch(token)!.group(1)!;
      final text = StringBuffer();
      for (var i = 0; i + 4 <= hex.length; i += 4) {
        final code = int.parse(hex.substring(i, i + 4), radix: 16);
        final rune = runes[code];
        if (rune != null && rune > 0) text.writeCharCode(rune);
      }
      runs.add(PdfTextRun(text.toString(), textX, textY, fontSize));
      pending.clear();
      continue;
    }
    switch (token) {
      case 'q':
        saved.add(ctm);
      case 'Q':
        ctm = saved.removeLast();
      case 'cm':
        ctm = _compose(ctm, [
          pending[0],
          pending[1],
          pending[2],
          pending[3],
          pending[4],
          pending[5],
        ]);
      case 'm' || 'l':
        pathPoints.add(_apply(ctm, pending[pending.length - 2], pending.last));
      case 'c':
        for (var i = pending.length - 6; i < pending.length; i += 2) {
          pathPoints.add(_apply(ctm, pending[i], pending[i + 1]));
        }
      case 're':
        final x = pending[pending.length - 4];
        final y = pending[pending.length - 3];
        pathPoints
          ..add(_apply(ctm, x, y))
          ..add(
            _apply(
              ctm,
              x + pending[pending.length - 2],
              y + pending[pending.length - 1],
            ),
          );
      case 'rg':
        fill = pending.sublist(pending.length - 3);
      case 'RG':
        stroke = pending.sublist(pending.length - 3);
      case 'f' || 'f*':
        if (pathPoints.isNotEmpty) paths.add(_pathOf(fill, pathPoints));
        pathPoints.clear();
      case 'S' || 's':
        if (pathPoints.isNotEmpty) {
          paths.add(_pathOf(stroke, pathPoints, filled: false));
        }
        pathPoints.clear();
      case 'Td':
        final at = _apply(ctm, pending[pending.length - 2], pending.last);
        textX = at[0];
        textY = at[1];
      case 'Tf':
        fontSize = pending.last;
      // Any other path-closing operator discards the collected points
      // (the clips and the multiline-paint combos are not needed; fills
      // and ink strokes are extracted above).
      default:
        if (pathPoints.isNotEmpty) pathPoints.clear();
    }
    pending.clear();
  }
  return (runs, paths);
}

// ---------------------------------------------------------------------------
// The in-plot chart-marks fixture: sex (one triple-timing day, one end-only
// day), mucus signs (S with quality, f/S), a mucus-peak mark on the S day and
// a Mittelschmerz day — on a continuous window (column == calendar offset
// from the Mar 1 cycle start), one page.
// ---------------------------------------------------------------------------

List<DailyEntry> markFixtureEntries() => [
  for (var i = 0; i < 14; i++)
    DailyEntry(
      date: d(3, 1 + i),
      bbtC: 36.5,
      sexTimings: i == 2
          ? (SexTiming.start.bit | SexTiming.middle.bit | SexTiming.end.bit)
          : (i == 3 ? SexTiming.end.bit : 0),
      mucusSign: i == 5 ? MucusSign.s : (i == 6 ? MucusSign.fs : null),
      mucusQuality: i == 5 ? MucusQuality.ew : null,
      painMittelschmerz: i == 8,
    ),
];

List<CycleMark> markFixtureMarks() => [
  CycleMark(date: d(3, 1), type: CycleMarkTypes.cycleStart),
  CycleMark(date: d(3, 6), type: CycleMarkTypes.mucusPeakDay),
];

PdfExportModel markFixtureModel({TemperatureRange? range}) =>
    buildPdfExportModel(
      entries: markFixtureEntries(),
      marks: markFixtureMarks(),
      temperatureRange: range ?? TemperatureRange.defaults,
      today: d(3, 14),
    );

Future<List<int>> generateMarkFixture({TemperatureRange? range}) =>
    generatePdfBytes(
      model: markFixtureModel(range: range),
      fontBytes: fixtureFontBytes(),
      options: PdfExportOptions(anonymized: false),
      compress: false,
    );

// ---------------------------------------------------------------------------
// The merged notes-band fixture: day 0 records the full stack (closed
// opening in the low slot + soft firmness + breast pain + note), day 1 an
// unreachable open cervix with the half-soft firmness alone, day 2 breast
// pain + note without any cervix observation and day 3 a middle opening
// in the middle slot alone — on a continuous window (column == calendar
// offset from the Mar 1 cycle start), one page.
// ---------------------------------------------------------------------------

List<DailyEntry> bandFixtureEntries() => [
  DailyEntry(
    date: d(3, 1),
    bbtC: 36.5,
    cervixPosition: CervixPosition.low,
    cervixOpening: CervixOpening.closed,
    cervixFirmness: CervixFirmness.soft,
    painBreast: true,
    notes: 'Erste Notiz',
  ),
  DailyEntry(
    date: d(3, 2),
    bbtC: 36.5,
    cervixPosition: CervixPosition.unreachable,
    cervixOpening: CervixOpening.open,
    cervixFirmness: CervixFirmness.halfSoft,
  ),
  DailyEntry(
    date: d(3, 3),
    bbtC: 36.5,
    painBreast: true,
    notes: 'Zweite Notiz',
  ),
  DailyEntry(
    date: d(3, 4),
    bbtC: 36.5,
    cervixPosition: CervixPosition.medium,
    cervixOpening: CervixOpening.middle,
  ),
  for (var i = 4; i < 14; i++) DailyEntry(date: d(3, 1 + i), bbtC: 36.5),
];

List<CycleMark> bandFixtureMarks() => [
  CycleMark(date: d(3, 1), type: CycleMarkTypes.cycleStart),
];

PdfExportModel bandFixtureModel() => buildPdfExportModel(
  entries: bandFixtureEntries(),
  marks: bandFixtureMarks(),
  today: d(3, 14),
);

Future<List<int>> generateBandFixture() => generatePdfBytes(
  model: bandFixtureModel(),
  fontBytes: fixtureFontBytes(),
  options: PdfExportOptions(anonymized: false),
  compress: false,
);

// The in-plot day-numbers fixture: six low measurements at 36.2, then the
// first higher on day 7 (marked) — the evaluation numbers the lows 6…1, and
// a mucus S on one low day anchors the rows' relative geometry. One page.
List<DailyEntry> numberFixtureEntries() => [
  for (var i = 0; i <= 7; i++)
    DailyEntry(
      date: d(3, 1 + i),
      bbtC: i <= 5 ? 36.2 : 36.8,
      mucusSign: i == 3 ? MucusSign.s : null,
    ),
];

List<CycleMark> numberFixtureMarks() => [
  CycleMark(date: d(3, 1), type: CycleMarkTypes.cycleStart),
  CycleMark(date: d(3, 7), type: CycleMarkTypes.firstHigherMeasurement),
];

PdfExportModel numberFixtureModel({TemperatureRange? range}) =>
    buildPdfExportModel(
      entries: numberFixtureEntries(),
      marks: numberFixtureMarks(),
      temperatureRange: range ?? TemperatureRange.defaults,
      today: d(3, 8),
    );

Future<List<int>> generateNumberFixture({TemperatureRange? range}) =>
    generatePdfBytes(
      model: numberFixtureModel(range: range),
      fontBytes: fixtureFontBytes(),
      options: PdfExportOptions(anonymized: false),
      compress: false,
    );

void main() {
  group('rail captions (the paper-form row legends)', () {
    test('the below-plot temperature value row\'s rail legend reads exactly '
        '"Temperatur in °C" (consistent with Zyklustag/Datum styling)', () {
      expect(pdfRailCaptionTemperatureValues, 'Temperatur in °C');
    });

    test('the day-number and date rows keep their legends', () {
      expect(pdfRailCaptionDayNumbers, 'Zyklustag');
      expect(pdfRailCaptionDates, 'Datum');
    });

    test('the legends are pairwise distinct labels', () {
      final captions = [
        pdfRailCaptionDayNumbers,
        pdfRailCaptionDates,
        pdfRailCaptionTemperatureValues,
      ];
      expect(captions.toSet(), hasLength(captions.length));
    });
  });

  group('header facts (pure)', () {
    test('a named export shows the identifying values and the numbers', () {
      final facts = pdfHeaderFacts(
        model: _fakeModel,
        anonymized: false,
        cycleIndex: 0,
      );

      expect(valueOf(facts, 'Name'), 'Maria Muster');
      // No birth date stored: the "—" convention.
      expect(valueOf(facts, 'Geburtsdatum'), '—');
      // The count is the page's ordinal (the "Zyklus" line's exact source
      // figure): outside-app 3 + this cycle's 0-based index 0 + 1.
      expect(valueOf(facts, 'Beobachtete Zyklen'), '4');
      expect(valueOf(facts, 'Kürzester Zyklus'), '27 Tage');
      expect(valueOf(facts, 'Früheste erste höhere Messung'), 'Zyklustag 14');
    });

    test('a stored birth date is formatted as the German calendar date', () {
      final model = PdfExportModel(
        cycles: const [],
        markOpenedIndexes: const [0],
        overlays: const [],
        observedCyclesOutsideApp: 0,
        name: null,
        birthDate: DateTime.utc(1980, 12, 24),
        shortestCycleLengths: [null],
        earliestFirstHigherCycleDays: [null],
      );
      final facts = pdfHeaderFacts(
        model: model,
        anonymized: false,
        cycleIndex: 0,
      );

      expect(valueOf(facts, 'Name'), '—');
      expect(valueOf(facts, 'Geburtsdatum'), '24.12.1980');
      // The count-up can never be empty: it IS the cycle's ordinal (≥ 1).
      expect(valueOf(facts, 'Beobachtete Zyklen'), '1');
      // A first cycle has no completed earlier cycle and no earlier rise:
      // the "—" convention on both statistics.
      expect(valueOf(facts, 'Kürzester Zyklus'), '—');
      expect(valueOf(facts, 'Früheste erste höhere Messung'), '—');
    });

    test('the anonymize toggle hides name and birth date REGARDLESS of the '
        'stored settings and marks the document', () {
      final facts = pdfHeaderFacts(
        model: _fakeModel,
        anonymized: true,
        cycleIndex: 0,
      );

      expect(
        valueOf(facts, 'Name'),
        'anonymisiert',
        reason: 'the stored name must never reach the document',
      );
      expect(
        valueOf(facts, 'Geburtsdatum'),
        '—',
        reason: 'the birth date stays hidden, even when stored',
      );
      expect(
        facts.map((f) => f.value),
        isNot(contains('Maria Muster')),
        reason: 'no identifying value anywhere in the header facts',
      );
      expect(
        facts.any(
          (f) => f.label == 'Anonymisierung' && f.value == 'anonymisiert',
        ),
        isTrue,
        reason: 'the marker line states that the export was anonymized',
      );
    });

    test('the earliest header fact prints "—" when the record fact has no '
        'umrandete value', () {
      final model = PdfExportModel(
        cycles: const [],
        markOpenedIndexes: const [0],
        overlays: const [],
        observedCyclesOutsideApp: 0,
        name: null,
        birthDate: null,
        shortestCycleLengths: [28],
        earliestFirstHigherCycleDays: [null],
      );
      final facts = pdfHeaderFacts(
        model: model,
        anonymized: false,
        cycleIndex: 0,
      );
      expect(valueOf(facts, 'Früheste erste höhere Messung'), '—');
    });

    test('the earliest header fact prints the record\'s umrandete figure '
        'as is — the header never derives a figure of its own', () {
      final model = PdfExportModel(
        cycles: const [],
        markOpenedIndexes: const [0],
        overlays: const [],
        observedCyclesOutsideApp: 0,
        name: null,
        birthDate: null,
        shortestCycleLengths: [28],
        earliestFirstHigherCycleDays: [14],
      );
      final facts = pdfHeaderFacts(
        model: model,
        anonymized: false,
        cycleIndex: 0,
      );
      expect(valueOf(facts, 'Früheste erste höhere Messung'), 'Zyklustag 14');
    });

    test('the three cumulative facts are read PER CYCLE at the given '
        'cycleIndex (the paper-form count-up point of view)', () {
      final model = PdfExportModel(
        cycles: const [],
        markOpenedIndexes: const [0, 1],
        overlays: const [],
        observedCyclesOutsideApp: 0,
        name: null,
        birthDate: null,
        shortestCycleLengths: [27, 25],
        earliestFirstHigherCycleDays: [14, 12],
      );
      final first = pdfHeaderFacts(
        model: model,
        anonymized: false,
        cycleIndex: 0,
      );
      final second = pdfHeaderFacts(
        model: model,
        anonymized: false,
        cycleIndex: 1,
      );
      expect(valueOf(first, 'Beobachtete Zyklen'), '1');
      expect(valueOf(first, 'Kürzester Zyklus'), '27 Tage');
      expect(valueOf(first, 'Früheste erste höhere Messung'), 'Zyklustag 14');
      expect(valueOf(second, 'Beobachtete Zyklen'), '2');
      expect(valueOf(second, 'Kürzester Zyklus'), '25 Tage');
      expect(valueOf(second, 'Früheste erste höhere Messung'), 'Zyklustag 12');
    });

    test('"Beobachtete Zyklen" is the SAME source figure as the "Zyklus N" '
        'header line: model.ordinalOf(cycleIndex) — the count and the '
        'cycle number cannot drift', () {
      final facts = pdfHeaderFacts(
        model: _fakeModel,
        anonymized: false,
        cycleIndex: 0,
      );
      expect(
        valueOf(facts, 'Beobachtete Zyklen'),
        '${_fakeModel.ordinalOf(0)}',
      );
    });

    group('the observation window fact (Zykluszeitraum)', () {
      test('the window row carries the exported cycle\'s dates WITH year', () {
        final facts = pdfHeaderFacts(
          model: _fakeModel,
          anonymized: false,
          cycleIndex: 0,
          cycleWindow: (
            first: DateTime.utc(2026, 3, 1),
            last: DateTime.utc(2026, 3, 28),
          ),
        );
        expect(valueOf(facts, 'Zykluszeitraum'), '01.03.2026 – 28.03.2026');
      });

      test('anonymization hides name and birth date, NOT the observation '
          'window — the year stays on the anonymized export too', () {
        final facts = pdfHeaderFacts(
          model: _fakeModel,
          anonymized: true,
          cycleIndex: 0,
          cycleWindow: (
            first: DateTime.utc(2026, 3, 29),
            last: DateTime.utc(2026, 5, 2),
          ),
        );
        expect(valueOf(facts, 'Zykluszeitraum'), '29.03.2026 – 02.05.2026');
        expect(valueOf(facts, 'Name'), 'anonymisiert');
      });

      test('a page outside any cycle facts (degenerate) keeps the "—"', () {
        final facts = pdfHeaderFacts(
          model: _fakeModel,
          anonymized: false,
          cycleIndex: 0,
        );
